use crate::aap::caps::http_client;
use crate::aap::caps::state_rw;
use crate::aap::caps::types::{FeedDocument, FetchFailure};

const ALLOWED_HOSTS: [&str; 4] = [
    "simonwillison.net",
    "rss.arxiv.org",
    "bytecodealliance.org",
    "lobste.rs",
];

struct Node;

/// Extract the lowercase host from an http(s) URL. Returns None for anything
/// that is not a plain http(s) URL, or that carries userinfo.
fn host_of(url: &str) -> Option<String> {
    let rest = url
        .strip_prefix("https://")
        .or_else(|| url.strip_prefix("http://"))?;
    let authority = rest
        .split(|c: char| matches!(c, '/' | '?' | '#'))
        .next()?;
    if authority.contains('@') {
        return None;
    }
    let host = authority.split(':').next()?;
    if host.is_empty() {
        return None;
    }
    Some(host.to_ascii_lowercase())
}

impl Guest for Node {
    fn run(subscriptions: SubscriptionList) -> FeedBatch {
        // Record the input this call received in the shared store.
        state_rw::put("last-input", &subscriptions.urls.join("\n"));

        let mut documents: Vec<FeedDocument> = Vec::new();
        let mut failures: Vec<FetchFailure> = Vec::new();

        for url in subscriptions.urls {
            match host_of(&url) {
                // Out-of-allowlist requests trap at the boundary, so they are
                // filtered here before reaching the capability.
                Some(host) if ALLOWED_HOSTS.contains(&host.as_str()) => {
                    match http_client::fetch(&url) {
                        Ok(body) => documents.push(FeedDocument { url, body }),
                        Err(error) => failures.push(FetchFailure { url, error }),
                    }
                }
                _ => failures.push(FetchFailure {
                    url,
                    error: "host not in allowlist".to_string(),
                }),
            }
        }

        FeedBatch {
            documents,
            failures,
        }
    }
}

export!(Node);
